import random

from trialops.eligibility import evaluate_subject


def ref_evaluate(subject, protocol, on):
    """Independent implementation written straight from the request text."""
    if not isinstance(on, date):  # datetime excluded below in the real code
        raise ValueError("on must be a date")

    birth = date.fromisoformat(subject["birth_date"])
    consents = subject["consents"]
    labs = subject["labs"]
    flags = set(subject["flags"])

    min_age = protocol["min_age"]
    max_age = protocol["max_age"]
    required_version = protocol["required_consent_version"]
    valid_from = date.fromisoformat(protocol["consent_valid_from"])
    protocol_labs = protocol["labs"]
    exclusions = protocol["exclusions"]

    selected = None
    for consent in consents:
        signed = date.fromisoformat(consent["signed_on"])
        if signed <= on and (selected is None or signed >= selected[0]):
            selected = (signed, consent["version"])

    reasons = []
    if selected is None or selected[0] < valid_from:
        reasons.append("CONSENT_MISSING")
    if selected is not None and selected[1] != required_version:
        reasons.append("CONSENT_VERSION")

    age = on.year - birth.year - ((on.month, on.day) < (birth.month, birth.day))
    if age < min_age:
        reasons.append("AGE_BELOW_MIN")
    if age > max_age:
        reasons.append("AGE_ABOVE_MAX")

    for flag in exclusions:
        if flag in flags:
            reasons.append("EXCLUSION_" + flag)

    lab_reasons = []
    for name in sorted(protocol_labs):
        low, high = protocol_labs[name]
        value = labs[name]
        if value < low:
            lab_reasons.append("LAB_" + name + "_LOW")
        elif value > high:
            lab_reasons.append("LAB_" + name + "_HIGH")
    reasons.extend(lab_reasons)

    return {
        "eligible": not reasons,
        "reasons": reasons,
        "consent_version": None if selected is None else selected[1],
    }


NAMES = ["A", "AB", "B", "Z", "a", "Z2"]
FLAGS = ["DO_NOT_ENROLL", "PRIOR", "OTHER"]
VERSIONS = ["v1", "v2", "v9"]


def random_date(rng):
    base = date(2000, 1, 1) + timedelta(days=rng.randrange(0, 12000))
    return base


def random_case(rng):
    on = random_date(rng)
    birth = on - timedelta(days=rng.randrange(0, 30000))
    n_consents = rng.randrange(0, 5)
    consents = []
    for _ in range(n_consents):
        signed = on - timedelta(days=rng.randrange(0, 800))
        if rng.random() < 0.15:
            signed = on  # same-day / exact boundary
        consents.append(
            {"version": rng.choice(VERSIONS), "signed_on": signed.isoformat()}
        )
    if consents and rng.random() < 0.2:
        # exact duplicate date with a different version (tie-break probe)
        consents.append(
            {"version": rng.choice(VERSIONS), "signed_on": consents[0]["signed_on"]}
        )
    lab_names = rng.sample(NAMES, rng.randrange(0, 4))
    labs = {name: rng.randrange(-5, 25) for name in lab_names}
    protocol_labs = {
        name: [rng.randrange(-5, 10), rng.randrange(10, 25)] for name in lab_names
    }
    if rng.random() < 0.3 and lab_names:
        name = rng.choice(lab_names)
        value = rng.choice(list(protocol_labs[name]))
        labs[name] = value  # exact boundary
    exclusions = rng.sample(FLAGS, rng.randrange(0, 4))
    subject = {
        "birth_date": birth.isoformat(),
        "consents": consents,
        "labs": labs,
        "flags": rng.sample(FLAGS, rng.randrange(0, 4)),
    }
    valid_from = random_date(rng)
    if rng.random() < 0.3 and consents:
        valid_from = date.fromisoformat(consents[0]["signed_on"])
    protocol = {
        "min_age": rng.randrange(0, 40),
        "max_age": 0,
        "required_consent_version": rng.choice(VERSIONS),
        "consent_valid_from": valid_from.isoformat(),
        "labs": protocol_labs,
        "exclusions": exclusions,
    }
    protocol["max_age"] = protocol["min_age"] + rng.randrange(0, 40)
    return subject, protocol, on


def test_differential_fuzz():
    mismatches = 0
    ties = 0
    for seed in range(20000):
        rng = random.Random(seed)
        subject, protocol, on = random_case(rng)
        # detect tie situations, which are spec-ambiguous
        dated = [
            date.fromisoformat(c["signed_on"])
            for c in subject["consents"]
            if date.fromisoformat(c["signed_on"]) <= on
        ]
        if dated and dated.count(max(dated)) > 1:
            ties += 1
        got = evaluate_subject(subject, protocol, on)
        want = ref_evaluate(subject, protocol, on)
        if got != want:
